-- Dragonmaw Race quests (11064, 11067, 11068, 11069, 11070, 11071): the six racers fly a course with the player
-- following on a flying mount, throw bombs that knock the rider off, and complete the quest when the course is done.
-- Scripts: npc_dragonmaw_racer (racer), npc_dragonmaw_race_target (bomb target).
-- The course of each racer is the order of its race target spawns in the 5.4.8 data (the places the bombs landed),
-- one waypoint per bomb salvo, flown 20 yards above the recorded height, ending above the racer's start.

UPDATE `creature_template` SET `ScriptName` = 'npc_dragonmaw_racer' WHERE `entry` IN (23340, 23342, 23344, 23345, 23346, 23348);
UPDATE `creature_template` SET `ScriptName` = 'npc_dragonmaw_race_target' WHERE `entry` IN (23356, 23357, 23358, 23359, 23360, 23361);

-- The quests complete through an event, like the other quests with a dummy objective.
DELETE FROM `quest_objective` WHERE `questId` IN (11064, 11067, 11068, 11069, 11070, 11071);

-- Waypoints: path id is the racer entry times 100.
DELETE FROM `waypoint_data` WHERE `id` IN (2334000, 2334200, 2334400, 2334500, 2334600, 2334800);

-- The knockdown spells pick their targets with the implicit target conditions: players only.
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 13 AND `SourceEntry` IN (40900, 40905, 40929, 40931);
